SELECT p.post_id, p.user_id, p.user_nickname, p.user_stage, p.avatar_url, p.content, p.is_deleted, p.created_at, p.updated_at, p.original_language, p.content_zh, p.content_en, p.content_ja, p.content_ko, p.content_de, p.content_fr, p.content_pt, p.content_es, p.translation_status, p.translated_at, p.emojiCountry, COALESCE(pl.like_count, 0) as upvotes, COALESCE(comment_counts.comment_count, 0) as comment_count, COUNT(*) OVER() as total_count FROM posts p LEFT JOIN post_likes pl ON p.post_id = pl.post_id LEFT JOIN (     SELECT post_id, COUNT(*) as comment_count     FROM comments     WHERE is_deleted = ?     GROUP BY post_id ) comment_counts ON p.post_id = comment_counts.post_id WHERE p.is_deleted = ? ORDER BY p.%s %s LIMIT ? OFFSET ?
